def sortAscending(nums): 
    #loop over the given list 
    for i in range(len(nums)): 
        #loop over the list for every item
        for j in range(i+1, len(nums)): 
            #if any item is greater than the item at this index, 
            #swap its positions
            if nums[i] > nums[j] : 
                nums[i], nums[j] = nums[j], nums[i] 

    #return the sorted list       
    return nums

from flask import Flask, request

app = Flask(__name__)

@app.route('/add_two_numbers', methods=['GET', 'POST'])
def add_two_numbers():
    if request.method == 'POST':
        # get data from the request 
        data = request.get_json()

        # extract the numbers from the data 
        num1 = data["num1"]
        num2 = data["num2"]

        # add the numbers 
        result = num1 + num2

        # return the response 
        return {'result': result}

if __name__ == '__main__':
    app.run()

